CREATE OR REPLACE FUNCTION public.sgp_aluminio_pendiente_crear(p_token text, p_reserva text, p_produccion text, p_perfil text, p_cantidad numeric, p_longitud numeric, p_origen text, p_causa text, p_observacion text, p_key_produccion text DEFAULT NULL::text, p_reserva_principal text DEFAULT NULL::text, p_acabado_pendiente text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare u text; id uuid; v_key text; v_principal text; v_shared boolean:=false; v_finish text; v_reserva text;
begin
 u:=public.sgp_validar_sesion_rol(p_token,array['ADMINISTRADOR','COORDINADOR','LIDER MECANIZADO','LIDER','LIDER LINEA']);
 v_reserva:=nullif(trim(coalesce(p_reserva,'')),'');
 v_key:=nullif(trim(coalesce(p_key_produccion,'')),'');
 v_principal:=nullif(trim(coalesce(p_reserva_principal,'')),'');
 if v_key is null and p_produccion is not null then
   select v.key_produccion,v.reserva_principal into v_key,v_principal
   from public.sgp_produccion_reservas_v v
   where v.produccion=p_produccion
     and (v_principal is null or v.reserva_principal=v_principal)
     and (v_reserva is null or v.reserva=v_reserva or v.reserva_principal=v_reserva)
   order by v.semana_produccion desc
   limit 1;
 end if;
 if v_principal is null and v_key is not null then
   select min(v.reserva_principal) into v_principal from public.sgp_produccion_reservas_v v where v.key_produccion=v_key;
 end if;
 v_principal:=coalesce(v_principal,v_reserva);
 if v_key is not null then
   select bool_or(v.es_reserva_compartida) into v_shared from public.sgp_produccion_reservas_v v where v.key_produccion=v_key;
   if v_reserva is null then v_reserva:=v_principal; end if;
   if not exists(select 1 from public.sgp_produccion_reservas_v v where v.key_produccion=v_key and v.reserva=v_reserva) then
     raise exception 'La reserva seleccionada no pertenece a esta producción';
   end if;
   select v.acabado_reserva into v_finish from public.sgp_produccion_reservas_v v where v.key_produccion=v_key and v.reserva=v_reserva limit 1;
 end if;
 v_finish:=coalesce(nullif(trim(coalesce(p_acabado_pendiente,'')),''),v_finish);
 insert into public.sgp_aluminio_pendientes(
   reserva,reserva_principal,key_produccion,es_reserva_compartida,acabado_pendiente,
   produccion,perfil,cantidad,longitud,origen,causa,observacion,usuario_reporte
 ) values(
   v_reserva,v_principal,v_key,coalesce(v_shared,false),v_finish,
   p_produccion,p_perfil,greatest(coalesce(p_cantidad,1),1),p_longitud,upper(coalesce(p_origen,'PRODUCCION')),p_causa,p_observacion,u
 ) returning id_pendiente into id;
 return id;
end $function$

CREATE OR REPLACE FUNCTION public.sgp_mecanizado_perfiles_reserva(p_token text, p_reserva text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare u text;
begin
 u:=sgp_validar_sesion_rol(p_token,array['ADMINISTRADOR','COORDINADOR','LIDER MECANIZADO','LIDER LINEA','RECEPCION','CONSULTA']);
 return coalesce((select jsonb_agg(to_jsonb(x) order by x.perfil,x.longitud) from(
   select a.codigo_sap perfil,max(a.descripcion) descripcion,a.longitud,round(sum(coalesce(a.cantidad,a.unidades,0)))::integer cantidad
   from sgp_aluminio a join sgp_producciones p on p.produccion=a.produccion
   where p.reserva_al=p_reserva and coalesce(a.codigo_sap,'')<>'' group by a.codigo_sap,a.longitud
 )x),'[]'::jsonb);
end $function$

